6 | async function walk(page:Page,x:number){const until=Date.now()+25000;let jump=0;while(true){const s=await read(page);if(!s.player){if(Date.now()>until)throw Error("Player did not load");await page.waitForTimeout(50);continue;}if(Math.abs(s.player.x-x)<12)break;if(Date.now()>until)throw Error(`Unreachable ${x}: ${JSON.stringify(s.player)}`);const key=s.player.x<x?'d':'a';await page.keyboard.up(key==='d'?'a':'d');await page.keyboard.down(key);if(Date.now()-jump>430){await page.keyboard.press('ArrowUp');jump=Date.now();}await page.waitForTimeout(65);}await page.keyboard.up('a');await page.keyboard.up('d');await page.waitForTimeout(600);}

